<script lang="ts">import{untrack}from'svelte';import{goto}from'$app/navigation';import{appState}from'./storage.svelte';import type{Recipe,Ingredient}from'./types';let{existing}: {existing?:Recipe}=$props();let initial=untrack(()=>existing);let title=$state(initial?.title||'');let category=$state(initial?.category||'');let area=$state(initial?.area||'');let imageUrl=$state(initial?.imageUrl||'');let instructions=$state(initial?.instructions||'');let ingredients=$state<Ingredient[]>(initial?.ingredients?.length?structuredClone(initial.ingredients):[{name:'',measure:''}]);let errors=$state<string[]>([]);function add(){ingredients=[...ingredients,{name:'',measure:''}]}function remove(i:number){ingredients=ingredients.filter((_,x)=>x!==i)}function save(e:SubmitEvent){e.preventDefault();errors=[];if(!title.trim())errors.push('Title is required.');if(!instructions.trim())errors.push('Instructions are required.');const valid=ingredients.filter(x=>x.name.trim());if(!valid.length)errors.push('Add at least one ingredient.');if(errors.length)return;const recipe:Recipe={id:existing?.id||crypto.randomUUID(),title:title.trim(),category:category.trim()||'User recipe',area:area.trim(),imageUrl:imageUrl.trim(),instructions:instructions.trim(),ingredients:valid,source:'user',createdAt:existing?.createdAt||new Date().toISOString()};appState.saveRecipe(recipe);goto('/my-recipes')}</script>
<form onsubmit={save} novalidate>{#if errors.length}<div class="errors" role="alert"><strong>Please fix:</strong><ul>{#each errors as e}<li>{e}</li>{/each}</ul></div>{/if}<div class="two"><label>Recipe title *<input bind:value={title}/></label><label>Category<input bind:value={category}/></label><label>Cuisine / area<input bind:value={area}/></label><label>Image URL<input type="url" bind:value={imageUrl}/></label></div><fieldset><legend>Ingredients *</legend>{#each ingredients as ing,i}<div class="ingredient"><input aria-label="Ingredient name" placeholder="Ingredient" bind:value={ing.name}/><input aria-label="Measurement" placeholder="Measurement" bind:value={ing.measure}/><button type="button" onclick={()=>remove(i)} disabled={ingredients.length===1}>Remove</button></div>{/each}<button type="button" onclick={add}>+ Add ingredient</button></fieldset><label>Instructions *<textarea rows="8" bind:value={instructions}></textarea></label><div class="actions"><button class="primary" type="submit">Save recipe</button><a href="/my-recipes">Cancel</a></div></form>
<style>form{display:grid;gap:18px}.two{display:grid;grid-template-columns:1fr 1fr;gap:15px}label{display:grid;gap:7px;font-weight:650}input,textarea{font:inherit;padding:11px;border:1px solid #abc2b3;border-radius:9px}.ingredient{display:grid;grid-template-columns:1fr 1fr auto;gap:8px;margin:8px 0}fieldset{border:1px solid #cfddd3;border-radius:12px}.errors{background:#fff0f0;color:#8a1717;padding:12px;border-radius:10px}.actions{display:flex;align-items:center;gap:15px}.primary,button{padding:10px 13px;border-radius:9px;border:1px solid #9eb9a7;background:white}.primary{background:#197149;color:white}@media(max-width:650px){.two,.ingredient{grid-template-columns:1fr}}</style>

